[
  {
    "title": "technique-helper-vocabulary",
    "claim": "Image #3’s stance helper names actions such as jump and crouch, while its technique helper names only directions, although Image #6 associates those directions with punch, reverse, kick, and sweep.",
    "reason": "Players can see what the stance stick does without opening the guide, but cannot get equivalent information for the technique stick.",
    "suggest": "Label the technique helper 'Forward: punch', 'Back: reverse', 'Up: kick', and 'Down: sweep', wrapping the text rather than shrinking it."
  },
  {
    "title": "pre-fight-help-not-visible",
    "claim": "Image #2 shows Fight and 'Starting in 2' without visible Moves or Settings buttons, whereas both buttons are visible in Image #3.",
    "reason": "The introduction presents starting the fight before presenting an on-screen way to learn the controls.",
    "suggest": "Add a clearly labeled Learn moves button to the introduction and suspend its starting countdown while the guide is open."
  },
  {
    "title": "impact-location-needs-verification",
    "claim": "Image #12 shows pale impact flecks around Asmongold’s hair above HasanAbi’s foot overlapping his upper torso, but the still cannot establish whether their separation reflects particle dispersion or an offset emitter.",
    "reason": "If the initial effect is misplaced, it could communicate a different contact location from the visible strike.",
    "suggest": "Capture the first contact frame with rendered contact and emitter-origin markers; align the emitter with the visible contact only if that comparison confirms an offset."
  },
  {
    "title": "settings-dismiss-placement",
    "claim": "Image #7’s visible Settings dismissal button is at the top-right, with no second dismissal button beneath the settings content.",
    "reason": "A lower dismissal option would let players resume nearer the bottom-positioned game controls.",
    "suggest": "Add a Back to fight button beneath the record text, retaining the existing top-right close button."
  },
  {
    "title": "boot-progress-not-verifiable",
    "claim": "Image #1 shows 'Downloading the game' and a progress track without a visibly distinct filled segment or textual progress value, so this still cannot establish whether loading is advancing.",
    "reason": "The visible state gives a waiting player little evidence for distinguishing initial loading from a stall.",
    "suggest": "Add a textual completed-work value driven by real boot milestones, and verify its updates against the bar in a cold-load recording rather than introducing timer-based progress."
  }
]
